from pathlib import Path

path = Path('index.html')
text = path.read_text(encoding='utf-8')

css_anchor = """    .pm-order-card { background: white; border: 1px solid #dfe7f1; border-radius: 14px; padding: 12px; box-shadow: 0 4px 14px rgba(26,54,93,.04); min-width: 0; }\n    .pm-full-preview-stage { min-height: 610px; border: 1px solid #e1e8f0; border-radius: 14px; background: linear-gradient(180deg, #f8fafc 0%, #eef4fa 100%); padding: 20px; display: flex; align-items: flex-start; justify-content: center; overflow: auto; }\n"""
css_replacement = """    .pm-order-card { background: white; border: 1px solid #dfe7f1; border-radius: 14px; padding: 12px; box-shadow: 0 4px 14px rgba(26,54,93,.04); min-width: 0; }\n    .pm-review-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; align-items: start; }\n    .pm-review-grid-card { min-width: 0; overflow: hidden; }\n    .pm-review-grid-stage { background: linear-gradient(180deg, #f8fafc 0%, #eef4fa 100%); border-top: 1px solid #edf1f6; border-bottom: 1px solid #edf1f6; padding: 10px; display: flex; align-items: flex-start; justify-content: center; overflow: auto; }\n    .pm-review-grid-details { padding: 12px; background: #fff; }\n    .pm-review-grid-output { min-height: 36px; }\n    @media (min-width: 1024px) { .pm-review-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }\n    @media (min-width: 1536px) { .pm-review-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }\n    .pm-full-preview-stage { min-height: 610px; border: 1px solid #e1e8f0; border-radius: 14px; background: linear-gradient(180deg, #f8fafc 0%, #eef4fa 100%); padding: 20px; display: flex; align-items: flex-start; justify-content: center; overflow: auto; }\n"""
if css_anchor not in text:
    raise SystemExit('CSS anchor not found')
text = text.replace(css_anchor, css_replacement, 1)

old_toggle = """<div className=\"flex p-1 bg-slate-100 rounded-lg\"><button onClick={()=>setPreviewMode('labels')} className={`pm-view-toggle ${previewMode==='labels'?'pm-view-toggle-active':''}`} title=\"พรีวิวเต็มหน้า\" aria-label=\"พรีวิวเต็มหน้า\"><PMIcon name=\"file\" className=\"w-4 h-4\"/></button><button onClick={()=>setPreviewMode('table')} className={`pm-view-toggle ${previewMode==='table'?'pm-view-toggle-active':''}`} title=\"มุมมองรายการ\" aria-label=\"มุมมองรายการ\"><PMIcon name=\"list\" className=\"w-4 h-4\"/></button></div>"""
new_toggle = """<div className=\"flex p-1 bg-slate-100 rounded-lg\"><button onClick={()=>setPreviewMode('labels')} className={`pm-view-toggle ${previewMode==='labels'?'pm-view-toggle-active':''}`} title=\"พรีวิวหลายใบ\" aria-label=\"พรีวิวหลายใบ\"><PMIcon name=\"file\" className=\"w-4 h-4\"/></button><button onClick={()=>setPreviewMode('table')} className={`pm-view-toggle ${previewMode==='table'?'pm-view-toggle-active':''}`} title=\"มุมมองรายการ\" aria-label=\"มุมมองรายการ\"><PMIcon name=\"list\" className=\"w-4 h-4\"/></button></div>"""
if old_toggle not in text:
    raise SystemExit('View toggle anchor not found')
text = text.replace(old_toggle, new_toggle, 1)

start_marker = """                    ):(\n                      <div data-pm-review-preview=\"full\" className=\"space-y-5\">\n"""
end_marker = """                      </div>\n                    )}\n\n                    {previewMode==='table'&&FilteredOrders.length>0&&"""
start = text.find(start_marker)
if start == -1:
    raise SystemExit('Preview start marker not found')
end = text.find(end_marker, start)
if end == -1:
    raise SystemExit('Preview end marker not found')

new_block = """                    ):(\n                      <div data-pm-review-preview=\"grid\" data-pm-review-layout=\"hybrid-grid\" className=\"pm-review-grid\">\n                        {FilteredOrders.map((order,index)=>{const flags=getReviewFlags(order);const row=exceptionRows.find(item=>item.order?.id===order.id);const totalQty=(order.parsedItems||[]).reduce((sum,item)=>sum+(Number(item.qty)||0),0)||order.originalQty||'-';return <article key={order.id} data-pm-review-preview-item className=\"pm-card pm-review-grid-card\">\n                          <div className=\"p-3 flex items-start justify-between gap-3\">\n                            <div className=\"min-w-0\">\n                              <div className=\"flex flex-wrap items-center gap-1.5\"><PMStatusPill tone={order.platform==='TIKTOK'?'dark':'orange'}>{order.platform==='TIKTOK'?'TikTok':'Shopee'}</PMStatusPill><span className=\"text-[9px] font-black text-slate-400\">ลำดับ {index+1}/{FilteredOrders.length}</span></div>\n                              <div className=\"mt-2 text-[9px] uppercase tracking-[.11em] font-black text-slate-400\">Order / Tracking</div>\n                              <div className=\"font-mono text-xs font-black text-slate-800 break-all mt-0.5\">{order.tracking||order.orderId||order.id}</div>\n                            </div>\n                            <div className=\"flex flex-wrap justify-end gap-1 max-w-[150px]\">{flags.ready&&<PMStatusPill tone=\"green\">พร้อมพิมพ์</PMStatusPill>}{flags.hasSkuReview&&<PMStatusPill tone=\"amber\">ตรวจสอบ SKU</PMStatusPill>}{flags.hasQtyReview&&<PMStatusPill tone=\"red\">ตรวจสอบ Qty</PMStatusPill>}{flags.hasUnmapped&&<PMStatusPill tone=\"slate\">ยังไม่ตั้งชื่อ</PMStatusPill>}</div>\n                          </div>\n                          <div className=\"pm-review-grid-stage\"><LabelCard order={order} thermalMode={thermalMode} /></div>\n                          <div data-pm-review-card-details className=\"pm-review-grid-details\">\n                            <div className=\"grid grid-cols-2 gap-2\"><div className=\"pm-mini-stat\"><span>Qty</span><strong>{totalQty}</strong></div><div className=\"pm-mini-stat\"><span>ลำดับ</span><strong>{index+1}/{FilteredOrders.length}</strong></div></div>\n                            <div className=\"mt-3\"><div className=\"text-[10px] font-black text-slate-500 mb-2\">ชื่อภายใน / ผลลัพธ์ที่จะพิมพ์</div><div className=\"pm-review-grid-output space-y-1.5\">{(order.displayItems||[]).map((text,idx)=><div key={idx} className={`rounded-lg px-2.5 py-2 text-xs font-black ${text.includes('ตรวจสอบ')||text.includes('ยังไม่ตั้งชื่อ')?'bg-red-50 text-red-700 border border-red-100':'bg-blue-50 text-blue-800 border border-blue-100'}`}>{text}</div>)}</div></div>\n                            {row&&(flags.hasSkuReview||flags.hasUnmapped)&&<button onClick={()=>handleFixSkuException(row)} className=\"pm-secondary-btn w-full justify-center mt-3\">ตั้งชื่อ SKU</button>}\n                          </div>\n                        </article>})}\n                      </div>\n                    )}\n\n                    {previewMode==='table'&&FilteredOrders.length>0&&"""

text = text[:start] + new_block + text[end + len(end_marker):]
path.write_text(text, encoding='utf-8')
